var e=`1423-nauruan-coconut-fish`;var t=`world-1423`;var a=`NR`;var o=`oceania`;var s=4;var l=26;var u={en:`Nauruan Coconut Fish`,ua:`Риба в кокосовому молоці по-науруанськи`};var r={en:`A Nauru-style fish dish gently simmered in coconut milk, onion, ginger and lime.`,ua:`Риба в кокосовому молоці по-науруанськи, ніжно тушкована з цибулею, імбиром та лаймом.`};var c=[{en:`Pat fish fillets dry and season lightly with salt.`,ua:`Обсушіть філе риби та злегка посоліть.`,t:[`seasoning`],m:4,i:[[`red-snapper`,650,`g`],[`sea-salt`,5,`g`]]},{en:`Sauté thinly sliced onion and chopped ginger in oil until fragrant.`,ua:`Обсмажте тонко нарізану цибулю та подрібнений імбир на олії до появи аромату.`,t:[`sauteing`],m:7,i:[[`yellow-onion`,160,`g`],[`ginger-root`,30,`g`],[`coconut-oil`,20,`ml`]]},{en:`Add coconut milk and bring to a gentle simmer. Slide in fish and poach covered about 10–12 minutes, until the thickest part reaches 63°C.`,ua:`Додайте кокосове молоко й доведіть до слабкого кипіння. Покладіть рибу й готуйте під кришкою приблизно 10–12 хвилин до 63°C у найтовщій частині.`,t:[`poaching`],m:12,i:[[`coconut-milk`,420,`ml`]]},{en:`Finish with lime juice, adjust seasoning and serve hot with rice or root vegetables.`,ua:`Наприкінці додайте сік лайма, відрегулюйте смак і подавайте гарячим із рисом або коренеплодами.`,t:[`finishing-with-acid`],m:3,i:[[`lime-juice`,35,`ml`]]}];var g={slug:e,id:t,country:`NR`,region:o,servings:4,minutes:26,title:u,text:r,steps:c};export{a as country,g as default,t as id,l as minutes,o as region,s as servings,e as slug,c as steps,r as text,u as title};